"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["37544"],{46173(n){n.exports=JSON.parse('{"id":11056,"title":"Python \u901A\u7528\u89C4\u8303","description":"---\\nalwaysApply: true\\ndescription: Python \u9879\u76EE\u5168\u5C40\u901A\u7528\u89C4\u8303\uFF0C\u59CB\u7EC8\u751F\u6548\\n---\\n\\n# Python \u901A\u7528\u5F00\u53D1\u89C4\u5219\\n## \u57FA\u7840\u683C\u5F0F\u89C4\u8303\\n1. \u7F29\u8FDB\uFF1A\u7EDF\u4E00\u4F7F\u7528 4 \u4E2A\u7A7A\u683C\uFF0C\u7981\u6B62 Tab \u7F29\u8FDB\uFF0C\u7981\u6B62\u7A7A\u683C+Tab \u6DF7\u7528\u3002\\n2. \u7F16\u7801\uFF1A\u6240\u6709 .py \u6587\u4EF6\u5934\u90E8\u6CE8\u660E `# -*- coding: UTF-8 -*-`\uFF0C\u4F7F\u7528 UTF-8 \u7F16\u7801\u3002\\n3. \u6362\u884C\uFF1A\u4E00\u884C\u53EA\u5199\u4E00\u6761\u8BED\u53E5\uFF0C\u903B\u8F91\u76F8\u5173\u7684\u591A\u884C\u4EE3\u7801\u4FDD\u6301\u7F29\u8FDB\u4E00\u81F4\u3002\\n4. \u7A7A\u884C\uFF1A\u51FD\u6570/\u7C7B\u4E4B\u95F4\u7A7A 2 \u884C\uFF0C\u51FD\u6570\u5185\u903B\u8F91\u5757\u4E4B\u95F4\u7A7A 1 \u884C\u3002\\n\\n## \u547D\u540D\u89C4\u8303\\n1. \u6A21\u5757/\u5305\u540D\uFF1Asnake_case\uFF0C\u5168\u5C0F\u5199+\u4E0B\u5212\u7EBF\uFF0C\u5982 `user_service.py`\u3001`data_process`\u3002\\n2. \u51FD\u6570/\u53D8\u91CF\u540D\uFF1Asnake_case\uFF0C\u5982 `get_user_name()`\u3001`order_id`\uFF0C\u7981\u6B62\u5355\u5B57\u7B26\u53D8\u91CF\uFF08i/j \u5FAA\u73AF\u53D8\u91CF\u9664\u5916\uFF09\u3002\\n3. \u7C7B\u540D\uFF1APascalCase\uFF0C\u5982 `UserService`\u3001`DataProcessor`\u3002\\n4. \u5E38\u91CF\u540D\uFF1AUPPER_SNAKE_CASE\uFF0C\u5982 `MAX_TIMEOUT`\u3001`DEFAULT_PAGE_SIZE`\uFF0C\u653E\u5728\u6A21\u5757\u9876\u90E8\u3002\\n\\n## \u8D28\u91CF\u7EA6\u675F\\n1. \u7C7B\u578B\u6CE8\u89E3\uFF1A\u6240\u6709\u51FD\u6570\u7684\u5165\u53C2\u3001\u8FD4\u56DE\u503C\u5FC5\u987B\u6DFB\u52A0\u7C7B\u578B\u6CE8\u89E3\uFF08\u5982 `def add(a: int, b: int) -> int`\uFF09\u3002\\n2. \u5F02\u5E38\u5904\u7406\uFF1A\u7981\u6B62\u88F8 try-except\uFF08`try: ... except:`\uFF09\uFF0C\u5FC5\u987B\u6355\u83B7\u5177\u4F53\u5F02\u5E38\uFF08\u5982 `ValueError`\uFF09\u3002\\n3. \u5371\u9669\u51FD\u6570\uFF1A\u7981\u6B62\u4F7F\u7528 eval()\u3001exec()\u3001input()\uFF08\u751F\u4EA7\u73AF\u5883\uFF09\u7B49\u5371\u9669\u51FD\u6570\u3002\\n4. \u8D44\u6E90\u7BA1\u7406\uFF1A\u6587\u4EF6\u3001\u6570\u636E\u5E93\u8FDE\u63A5\u4F7F\u7528 with \u8BED\u53E5\u81EA\u52A8\u5173\u95ED\uFF0C\u907F\u514D\u8D44\u6E90\u6CC4\u9732\u3002\\n\\n## \u5BFC\u5165\u89C4\u8303\\n1. \u5BFC\u5165\u987A\u5E8F\uFF1A\u6807\u51C6\u5E93 \u2192 \u7B2C\u4E09\u65B9\u5E93 \u2192 \u9879\u76EE\u5185\u90E8\u6A21\u5757\uFF0C\u6BCF\u7EC4\u4E4B\u95F4\u7A7A 1 \u884C\u3002\\n2. \u5BFC\u5165\u65B9\u5F0F\uFF1A\u7981\u6B62\u901A\u914D\u7B26\u5BFC\u5165\uFF08`from xxx import *`\uFF09\uFF0C\u7981\u6B62\u5FAA\u73AF\u5BFC\u5165\u3002\\n3. \u522B\u540D\u89C4\u8303\uFF1A\u5E38\u7528\u5E93\u522B\u540D\u7EDF\u4E00\uFF08import numpy as np, import pandas as pd\uFF09\u3002","remark":"Trae \u4E13\u5C5E","notes":"Python \u901A\u7528\u89C4\u8303 python-general.md\\n.trae/rules \u76EE\u5F55\u4E0B\u521B\u5EFA","owner":"\u5FC3\u68A6\u65E0\u75D5","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:39:03.275Z"}')}}]);